import ast
import sys

# Parse the final.py file
with open('/home/agent/final.py', 'r') as f:
    content = f.read()

try:
    ast.parse(content)
    print('✓ Syntax is valid')
except SyntaxError as e:
    print(f'✗ Syntax error: {e}')
    sys.exit(1)

# Check for critical imports
required_imports = [
    'pandas', 'numpy', 'torch', 'torchvision', 'sklearn.metrics', 'sklearn.model_selection'
]

for imp in required_imports:
    if imp in content or imp.replace('.', '_') in content:
        print(f'✓ Import {imp} found')
    else:
        print(f'✗ Import {imp} NOT found')

# Check for critical functions
critical_functions = [
    'train_test_split', 'roc_auc_score', 'submission.to_csv', 'os.makedirs'
]

for func in critical_functions:
    if func in content:
        print(f'✓ Function {func} found')
    else:
        print(f'✗ Function {func} NOT found')
